-- Explicações por artigo — Estatuto da Pessoa Idosa (Lei nº 10.741, de 2003). Texto-base: dispositivos oficiais já cadastrados em legal_course_units.

-- Rascunhos em revisão. Publicação exige revisão explícita; reexecução preserva qualquer registro existente.

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É instituído o Estatuto da Pessoa Idosa, destinado a regular os direitos assegurados às pessoas com idade igual ou superior a 60 anos.', '["Estatuto da Pessoa Idosa.","Pessoa idosa: idade igual ou superior a 60 anos."]'::jsonb, '["ATUALIZAÇÃO: a Lei nº 14.423, de 2022, trocou a expressão ''idoso'' por ''pessoa idosa'' em todo o Estatuto.","Critério etário: 60 anos."]'::jsonb, 'Quem tem 60 anos já é pessoa idosa para o Estatuto.', '["Assertiva que fixa em 65 anos a idade da pessoa idosa no Estatuto erra: são 60 anos."]'::jsonb, '[]'::jsonb, '["Art. 34"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-1' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'd378cc0e86429d07ad4804a9a9e552d5fb73024880e5a0392245a4a93b0d8ecb'
