and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A pessoa idosa goza de todos os direitos fundamentais inerentes à pessoa humana, sem prejuízo da proteção integral da Lei, assegurando-se-lhe todas as oportunidades e facilidades para preservação de sua saúde física e mental e seu aperfeiçoamento moral, intelectual, espiritual e social, em condições de liberdade e dignidade.', '["Todos os direitos fundamentais.","Proteção integral.","Liberdade e dignidade."]'::jsonb, '["Princípio da proteção integral."]'::jsonb, 'A pessoa idosa tem os mesmos direitos fundamentais de qualquer pessoa, com proteção adicional.', '["Assertiva que restringe os direitos fundamentais da pessoa idosa erra."]'::jsonb, '[]'::jsonb, '["Art. 3º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-2' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'bc9df8dcab831a6cfd2acf6dd5a9a68f2d6a53efd9fb209f3cbf9a233483b7c7'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É obrigação da família, da comunidade, da sociedade e do poder público assegurar à pessoa idosa, com absoluta prioridade, a efetivação dos direitos à vida, saúde, alimentação, educação, cultura, esporte, lazer, trabalho, cidadania, liberdade, dignidade, respeito e convivência familiar e comunitária. A prioridade compreende atendimento preferencial imediato e individualizado; preferência na formulação e execução de políticas sociais; destinação privilegiada de recursos públicos; formas alternativas de participação e convívio com as demais gerações; priorização do atendimento pela própria família, em detrimento do asilar, exceto para quem não a possua ou careça de condições; capacitação de recursos humanos em geriatria e gerontologia; divulgação de informações educativas sobre o envelhecimento; e acesso à rede de saúde e assistência social.', '["Obrigação da família, da comunidade, da sociedade e do poder público.","Absoluta prioridade.","Atendimento preferencial imediato e individualizado.","Preferência pelo atendimento familiar, e não asilar."]'::jsonb, '["A prioridade é ABSOLUTA.","Atendimento pela família tem preferência sobre o asilar."]'::jsonb, 'A pessoa idosa tem atendimento preferencial imediato em repartições públicas e privadas.', '["Assertiva que atribui o dever de proteger a pessoa idosa apenas ao Estado erra: é também da família, da comunidade e da sociedade."]'::jsonb, '[]'::jsonb, '["Art. 71"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-3' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '4274a20962f884487279aaadf91dd30a1dfd38d4dd2a62b4b602b663d04a0e34'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nenhuma pessoa idosa será objeto de qualquer tipo de negligência, discriminação, violência, crueldade ou opressão, e todo atentado aos seus direitos, por ação ou omissão, será punido na forma da lei. É dever de todos prevenir a ameaça ou violação aos seus direitos. As obrigações da Lei não excluem outras decorrentes dos princípios por ela adotados.', '["Vedadas negligência, discriminação, violência, crueldade e opressão.","Punição por ação ou omissão.","Dever de todos de prevenir."]'::jsonb, '["Dever de prevenir é de TODOS."]'::jsonb, 'O vizinho que percebe maus-tratos deve agir para preveni-los.', '["Assertiva que limita o dever de prevenção aos órgãos públicos erra: é de todos."]'::jsonb, '[]'::jsonb, '["Art. 5º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-4' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '4c6a06c9c41d54b6c49822fbdefd402d6e2bdf76b71e838d5409fa8036c0d649'
