insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É assegurada a atenção integral à saúde da pessoa idosa, por intermédio do SUS, com acesso universal e igualitário, em conjunto articulado e contínuo de ações e serviços para prevenção, promoção, proteção e recuperação da saúde, incluindo atenção especial às doenças que afetam preferencialmente as pessoas idosas. A prevenção e a manutenção da saúde serão efetivadas por cadastramento da população idosa, atendimento geriátrico e gerontológico em ambulatórios, unidades geriátricas de referência, atendimento domiciliar e reabilitação orientada pela geriatria e gerontologia. Incumbe ao poder público fornecer gratuitamente medicamentos, especialmente os de uso continuado, próteses, órteses e outros recursos relativos ao tratamento, habilitação ou reabilitação. É vedada a discriminação na cobrança de planos de saúde pela idade.', '["Atenção integral pelo SUS.","Cadastro, atendimento geriátrico, domiciliar e reabilitação.","Medicamentos, próteses e órteses gratuitos.","Vedada a discriminação nos planos de saúde por idade."]'::jsonb, '["ATUALIZAÇÃO: o §3º veda a cobrança diferenciada nos planos de saúde por faixa etária.","Medicamentos gratuitos, em especial os de uso continuado."]'::jsonb, 'O SUS fornece gratuitamente o remédio de uso contínuo da pessoa idosa.', '["Assertiva que permite ao plano de saúde cobrar mais apenas pela idade erra: é vedada a discriminação."]'::jsonb, '[]'::jsonb, '["Art. 16"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-15' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'c1161f3f446c2149c187db16ac43bb5534d50f5a67c72e0f0d7e8164c8ea5bcf'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'À pessoa idosa internada ou em observação é assegurado o direito a acompanhante, devendo o órgão de saúde proporcionar as condições adequadas para a sua permanência em tempo integral, segundo o critério médico. Caberá ao profissional de saúde responsável conceder a autorização para o acompanhamento ou, no caso de impossibilidade, justificá-la por escrito.', '["Direito a acompanhante em tempo integral.","Autorização do profissional de saúde, ou justificativa escrita da negativa."]'::jsonb, '["A negativa deve ser justificada por escrito."]'::jsonb, 'O hospital permite que o filho fique com o pai idoso internado.', '["Assertiva que permite negar o acompanhante sem justificativa escrita erra."]'::jsonb, '[]'::jsonb, '["Art. 15"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-16' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'c2e3486e20de68be6f46f88df2eaecdf27d86e39d7ca107b66547227211a24dc'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'À pessoa idosa que esteja no domínio de suas faculdades mentais é assegurado o direito de optar pelo tratamento de saúde que lhe for reputado mais favorável. Não estando em condições de optar, a opção será feita pelo curador, quando interditada; pelos familiares, quando não tiver curador ou este não puder ser contactado em tempo hábil; pelo médico, em iminente risco de vida sem tempo hábil para consulta; ou pelo próprio médico, quando não houver curador ou familiar conhecido, comunicando o fato ao Ministério Público.', '["Autonomia da pessoa idosa lúcida.","Ordem de decisão: curador, familiares, médico em risco de vida e médico com comunicação ao MP."]'::jsonb, '["Autonomia para escolher o tratamento."]'::jsonb, 'A pessoa idosa lúcida decide por qual tratamento será submetida.', '["Assertiva que transfere sempre a decisão aos familiares erra: a pessoa lúcida decide."]'::jsonb, '[]'::jsonb, '["Art. 15"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-17' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '2bc629760248b810d899fb3ff3b53a42431f20a0b2efc53ebc47ede0588499b9'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As instituições de saúde devem atender aos critérios mínimos para o atendimento às necessidades da pessoa idosa, promovendo o treinamento e a capacitação dos profissionais, assim como orientação a cuidadores familiares e grupos de autoajuda.', '["Critérios mínimos de atendimento.","Capacitação dos profissionais.","Orientação a cuidadores familiares."]'::jsonb, '["Inclui orientação a cuidadores e grupos de autoajuda."]'::jsonb, 'O hospital treina a equipe e orienta os cuidadores familiares.', '["Assertiva que dispensa capacitação dos profissionais de saúde erra."]'::jsonb, '[]'::jsonb, '["Art. 15"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-18' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '5774db09d8cfa685b2bacf07585d7a205f9261c0360767ec55917f607418c5ed'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os casos de suspeita ou confirmação de violência contra pessoas idosas serão objeto de notificação compulsória pelos serviços de saúde públicos e privados à autoridade sanitária, e obrigatoriamente comunicados a quaisquer dos seguintes órgãos: autoridade policial, Ministério Público, Conselho Municipal, Estadual ou Nacional da Pessoa Idosa. Considera-se violência qualquer ação ou omissão, em local público ou privado, que cause morte, dano ou sofrimento físico ou psicológico. Aplica-se, no que couber, a lei de notificação compulsória de doenças.', '["Notificação compulsória da suspeita ou confirmação de violência.","Comunicação a polícia, MP ou Conselhos.","Conceito amplo de violência."]'::jsonb, '["Basta a SUSPEITA para notificar.","Violência inclui a omissão."]'::jsonb, 'O hospital notifica a suspeita de maus-tratos à autoridade sanitária e ao Ministério Público.', '["Assertiva que exige a confirmação da violência para a notificação erra: basta a suspeita."]'::jsonb, '[]'::jsonb, '["Art. 57"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-19' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '25ffed1a7c41c8e40844937f078f2b2ff00fd1c7af9611985b136a76d73ddf3b'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A pessoa idosa tem direito a educação, cultura, esporte, lazer, diversões, espetáculos, produtos e serviços que respeitem sua peculiar condição de idade.', '["Direito a educação, cultura, esporte e lazer adequados à idade."]'::jsonb, '["Respeito à peculiar condição de idade."]'::jsonb, 'A pessoa idosa tem direito a atividades culturais adaptadas.', '["Assertiva que exclui a pessoa idosa da educação formal erra."]'::jsonb, '[]'::jsonb, '["Art. 21"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-20' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'd17aa1578c0e76e7c1fe83143cef1b0b831e5036d546ca1b7f5c2aa7df2e2346'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
