insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O poder público criará oportunidades de acesso da pessoa idosa à educação, adequando currículos, metodologias e material didático aos programas educacionais a ela destinados. Os cursos especiais incluirão conteúdo sobre técnicas de comunicação, computação e demais avanços tecnológicos. As pessoas idosas participarão das comemorações cívicas ou culturais, para transmissão de conhecimentos e vivências às demais gerações.', '["Currículos e materiais adaptados.","Cursos com conteúdo tecnológico.","Participação em comemorações para transmitir vivências."]'::jsonb, '["Inclusão digital da pessoa idosa."]'::jsonb, 'Um curso de informática é oferecido à pessoa idosa pelo poder público.', '["Assertiva que veda cursos de computação para pessoas idosas erra: eles são previstos."]'::jsonb, '[]'::jsonb, '["Art. 25"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-21' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'b2ce39ff1df470e12a3f8f03d2dd62d71ee216bbcd0bc84ab8c8bdfb3554a948'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
