insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos currículos mínimos dos diversos níveis de ensino formal serão inseridos conteúdos voltados ao processo de envelhecimento, ao respeito e à valorização da pessoa idosa, de forma a eliminar o preconceito e a produzir conhecimentos sobre a matéria.', '["Conteúdos sobre envelhecimento nos currículos."]'::jsonb, '["Combate ao preconceito etário (etarismo)."]'::jsonb, 'A escola ensina sobre envelhecimento e respeito à pessoa idosa.', '["Assertiva que restringe esses conteúdos ao ensino superior erra: aplicam-se a todos os níveis."]'::jsonb, '[]'::jsonb, '["Art. 21"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-22' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '5d135e6a2c64198212550f240801eccfe436e83bdce0154d10fb3d9050c203e2'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
