insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A participação das pessoas idosas em atividades culturais e de lazer será proporcionada mediante descontos de pelo menos 50% nos ingressos para eventos artísticos, culturais, esportivos e de lazer, bem como o acesso preferencial aos respectivos locais.', '["Desconto mínimo de 50% nos ingressos.","Acesso preferencial."]'::jsonb, '["Desconto de PELO MENOS 50%."]'::jsonb, 'A pessoa idosa paga meia-entrada no cinema, ou menos.', '["Assertiva que fixa o desconto máximo em 50% erra: é de pelo menos 50%."]'::jsonb, '[]'::jsonb, '["Art. 20"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-23' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'ba6410c28c315665a47bcd3d1bfad5704c641ebf444a312fb169be59296a8b4a'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
