select u.id, u.content_sha256, 'Os meios de comunicação manterão espaços ou horários especiais voltados às pessoas idosas, com finalidade informativa, educativa, artística e cultural, e ao público sobre o processo de envelhecimento.', '["Espaços ou horários especiais na mídia."]'::jsonb, '["Finalidade informativa, educativa, artística e cultural."]'::jsonb, 'A emissora mantém programa educativo sobre envelhecimento.', '["Assertiva que dispensa espaços voltados à pessoa idosa na mídia erra."]'::jsonb, '[]'::jsonb, '["Art. 20"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-24' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '926fe6e31e60f61b6378935b5443ba57bab906e7c6bcf38920c76583b044def1'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
