select u.id, u.content_sha256, 'A pessoa idosa tem direito ao exercício de atividade profissional, respeitadas suas condições físicas, intelectuais e psíquicas.', '["Direito ao trabalho, respeitadas as condições da pessoa."]'::jsonb, '["Respeito às condições físicas, intelectuais e psíquicas."]'::jsonb, 'A pessoa idosa pode continuar trabalhando, se tiver condições.', '["Assertiva que impede o trabalho após os 60 anos erra."]'::jsonb, '[]'::jsonb, '["Art. 27"]'::jsonb, 'under_review', 'claude'
