insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na admissão da pessoa idosa em qualquer trabalho ou emprego, são vedadas a discriminação e a fixação de limite máximo de idade, inclusive para concursos, ressalvados os casos em que a natureza do cargo o exigir. O primeiro critério de desempate em concurso público será a idade, com preferência ao de idade mais elevada.', '["Vedada a discriminação e o limite máximo de idade.","Exceção: natureza do cargo.","Primeiro desempate em concurso: idade mais elevada."]'::jsonb, '["Desempate em concurso: a PESSOA MAIS VELHA tem preferência."]'::jsonb, 'Em empate no concurso, vence o candidato de idade mais elevada.', '["Assertiva que dá preferência ao candidato mais novo no desempate erra: é ao de idade mais elevada."]'::jsonb, '[]'::jsonb, '["Art. 26"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-27' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'a29b810415f7b863dc5246ebfc1906f2ebbfd468ee27b2c193a96459e343fb88'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
