insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Poder Público criará e estimulará programas de profissionalização especializada para as pessoas idosas, aproveitando seus potenciais; de preparação dos trabalhadores para a aposentadoria, com antecedência mínima de 1 ano; e de estímulo às empresas privadas para admissão de pessoas idosas ao trabalho.', '["Profissionalização especializada.","Preparação para a aposentadoria com antecedência mínima de 1 ano.","Estímulo às empresas para contratar pessoas idosas."]'::jsonb, '["Antecedência mínima de 1 ano."]'::jsonb, 'A empresa prepara o trabalhador para a aposentadoria um ano antes.', '["Assertiva que fixa em seis meses a antecedência da preparação erra: é de 1 ano."]'::jsonb, '[]'::jsonb, '["Art. 27"]'::jsonb, 'under_review', 'claude'
