insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os benefícios de aposentadoria e pensão do Regime Geral da Previdência Social observarão, na concessão, critérios de cálculo que preservem o valor real dos salários sobre os quais incidiu contribuição. Os valores dos benefícios em manutenção serão reajustados na mesma data de reajuste do salário-mínimo, pro rata, conforme as datas de início ou do último reajustamento, com base em percentual definido em regulamento, observados os critérios da Lei nº 8.213, de 24 de julho de 1991.', '["Preservação do valor real dos salários de contribuição.","Reajuste na data do salário-mínimo, pro rata."]'::jsonb, '["ATUALIZAÇÃO: as regras de reajuste previdenciário foram alteradas por leis posteriores."]'::jsonb, 'O benefício é reajustado na mesma época do salário-mínimo.', '["Assertiva que reajusta os benefícios em data distinta do salário-mínimo erra."]'::jsonb, '[]'::jsonb, '["Art. 30"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-29' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '7e6f1817727fa8d3b4396375605b58c5a22e235b4239dc3a7a9a379bd4ac1b53'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A perda da condição de segurado não será considerada para a concessão da aposentadoria por idade, desde que a pessoa conte com, no mínimo, o tempo de contribuição correspondente ao exigido para efeito de carência na data do requerimento. O cálculo do valor observará a regra do art. 3º da Lei nº 9.876, de 26 de novembro de 1999, ou, não havendo salários-de-contribuição a partir de julho de 1994, o art. 35 da Lei nº 8.213, de 1991.', '["Perda da qualidade de segurado não impede a aposentadoria por idade.","Exige o tempo de carência.","Regras de cálculo específicas."]'::jsonb, '["Tempo de contribuição igual à carência na data do requerimento."]'::jsonb, 'Quem perdeu a qualidade de segurado, mas cumpriu a carência, ainda se aposenta por idade.', '["Assertiva que nega a aposentadoria por idade a quem perdeu a qualidade de segurado erra, se a carência foi cumprida."]'::jsonb, '[]'::jsonb, '["Art. 29"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-30' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '64529e62233d163f5c4e0e00b3fff97c41e98bd2c53b94989d6687feab0fd8ea'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
