insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Todas as entidades de longa permanência, ou casa-lar, são obrigadas a firmar contrato de prestação de serviços com a pessoa idosa abrigada. Nas entidades filantrópicas ou casas-lares é facultada a cobrança de participação da pessoa idosa no custeio, que não poderá exceder 70% de qualquer benefício previdenciário ou de assistência social percebido, forma estabelecida pelo Conselho Municipal da Pessoa Idosa ou da Assistência Social. Se a pessoa idosa for incapaz, o contrato será firmado por seu representante legal.', '["Contrato obrigatório com a pessoa abrigada.","Participação no custeio limitada a 70% do benefício.","Representante legal assina se a pessoa for incapaz."]'::jsonb, '["Teto de 70% do benefício."]'::jsonb, 'A entidade filantrópica cobra, no máximo, 70% da aposentadoria da pessoa abrigada.', '["Assertiva que fixa em 100% do benefício o limite da cobrança erra: é de 70%."]'::jsonb, '[]'::jsonb, '["Art. 50"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-35' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '046374142ef60d6b0769cf25ae85c6aef6bab9980053e889c009d7d068adacd0'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O acolhimento de pessoas idosas em situação de risco social, por adulto ou núcleo familiar, caracteriza a dependência econômica, para os efeitos legais.', '["Acolhimento caracteriza dependência econômica."]'::jsonb, '["Vigência a partir de 1º de janeiro de 2004 (art. 118)."]'::jsonb, 'Quem acolhe uma pessoa idosa em risco social tem a dependência econômica reconhecida para fins legais.', '["Assertiva que nega efeitos legais ao acolhimento de pessoa idosa erra."]'::jsonb, '[]'::jsonb, '["Art. 118"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-36' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '435ef1d90070c43b482a4cb235b598c3ddcfc923aa8561d805d6b62a712fa600'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A pessoa idosa tem direito a moradia digna, no seio da família natural ou substituta, ou desacompanhada de seus familiares, quando assim o desejar, ou em instituição pública ou privada. A assistência integral em entidade de longa permanência será prestada quando verificada inexistência de grupo familiar, casa-lar, abandono ou carência de recursos. Toda instituição fica obrigada a manter identificação externa visível, sob pena de interdição. As instituições devem manter padrões de habitação compatíveis, alimentação regular e higiene.', '["Moradia digna em família, sozinha ou em instituição.","Entidade de longa permanência é subsidiária.","Identificação externa visível, sob pena de interdição."]'::jsonb, '["Institucionalização é subsidiária."]'::jsonb, 'A pessoa idosa pode morar sozinha, se assim o desejar.', '["Assertiva que obriga a internação em instituição de pessoa idosa que quer morar sozinha erra."]'::jsonb, '[]'::jsonb, '["Art. 49"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-37' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '5b10441d339869ae110b8ba52d5e9e1ba6ee0169408534870d752df4308ea711'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos programas habitacionais, públicos ou subsidiados com recursos públicos, a pessoa idosa goza de prioridade na aquisição de imóvel para moradia própria, observada a reserva de pelo menos 3% das unidades residenciais; a implantação de equipamentos urbanos comunitários; a eliminação de barreiras arquitetônicas; e critérios de financiamento compatíveis com aposentadoria e pensão. As unidades reservadas devem situar-se preferencialmente no pavimento térreo.', '["Reserva de pelo menos 3% das unidades.","Eliminação de barreiras.","Financiamento compatível com a aposentadoria.","Preferência por pavimento térreo."]'::jsonb, '["Reserva mínima de 3%."]'::jsonb, 'Em um conjunto habitacional público, 3% das unidades são para pessoas idosas.', '["Assertiva que fixa em 10% a reserva de unidades erra: é de pelo menos 3%."]'::jsonb, '[]'::jsonb, '["Art. 37"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-38' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '218f483aba3f37b0b6dae47a9c3ea96cd4c464969443a48e38895e38c61ebfd7'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aos maiores de 65 anos fica assegurada a gratuidade dos transportes coletivos públicos urbanos e semiurbanos, exceto nos serviços seletivos e especiais prestados paralelamente aos regulares. Basta apresentar documento pessoal que prove a idade. Serão reservados 10% dos assentos para pessoas idosas, identificados. Para a faixa de 60 a 65 anos, a legislação local dispõe sobre a gratuidade.', '["Gratuidade para maiores de 65 anos.","Exceção: serviços seletivos e especiais paralelos.","Reserva de 10% dos assentos.","60 a 65 anos: critério da lei local."]'::jsonb, '["Gratuidade: 65 anos.","Reserva de 10% dos assentos."]'::jsonb, 'A pessoa de 66 anos viaja de graça no ônibus urbano apresentando documento.', '["Assertiva que garante gratuidade a partir de 60 anos em todos os casos erra: são 65 anos."]'::jsonb, '[]'::jsonb, '["Art. 40"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-39' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'e2c52ddb9a8281817770e4a32a03340cab15d4523581aa53a9c8af0ca43a4317'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No sistema de transporte coletivo interestadual observar-se-á, nos termos da legislação específica, a reserva de 2 vagas gratuitas por veículo para pessoas idosas com renda igual ou inferior a 2 salários mínimos, e desconto de 50%, no mínimo, no valor das passagens para as pessoas idosas que excederem as vagas gratuitas, com renda igual ou inferior a 2 salários mínimos. Os órgãos competentes definem os mecanismos e critérios.', '["2 vagas gratuitas por veículo.","Renda de até 2 salários mínimos.","Desconto mínimo de 50% nas passagens excedentes."]'::jsonb, '["2 vagas gratuitas e desconto de no mínimo 50%."]'::jsonb, 'No ônibus interestadual, duas vagas por veículo são gratuitas para pessoas idosas de baixa renda.', '["Assertiva que fixa 4 vagas gratuitas por veículo erra: são 2."]'::jsonb, '[]'::jsonb, '["Art. 39"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-40' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '10905d2a602b030b9101c5b81e52c0899858a7c2564ab2260aad2686d380a72b'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
