insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É assegurada a reserva para as pessoas idosas, nos termos da lei local, de 5% das vagas nos estacionamentos públicos e privados, posicionadas de forma a garantir a melhor comodidade à pessoa idosa.', '["Reserva de 5% das vagas.","Estacionamentos públicos e privados."]'::jsonb, '["Reserva de 5% das vagas."]'::jsonb, 'O estacionamento do mercado reserva 5% das vagas para pessoas idosas.', '["Assertiva que fixa em 2% a reserva de vagas erra: é de 5%."]'::jsonb, '[]'::jsonb, '["Art. 42"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-41' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'b4311f34bc42335f2ef22b0dab16f300c046e4f04f61e0bf7a49b0eb04180903'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
