select u.id, u.content_sha256, 'São asseguradas a prioridade e a segurança da pessoa idosa nos procedimentos de embarque e desembarque nos veículos do sistema de transporte coletivo.', '["Prioridade e segurança no embarque e desembarque."]'::jsonb, '["Prioridade E segurança."]'::jsonb, 'O motorista aguarda a pessoa idosa sentar antes de partir.', '["Assertiva que dispensa a segurança no embarque da pessoa idosa erra."]'::jsonb, '[]'::jsonb, '["Art. 39"]'::jsonb, 'under_review', 'claude'
