insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As medidas de proteção à pessoa idosa são aplicáveis sempre que os direitos reconhecidos na Lei forem ameaçados ou violados por ação ou omissão da sociedade ou do Estado; por falta, omissão ou abuso da família, curador ou entidade de atendimento; ou em razão de sua condição pessoal.', '["Ação ou omissão da sociedade ou do Estado.","Falta, omissão ou abuso da família, curador ou entidade.","Condição pessoal."]'::jsonb, '["Três hipóteses de aplicação das medidas de proteção."]'::jsonb, 'A negligência da família permite aplicar medidas de proteção.', '["Assertiva que restringe as medidas à violação pelo Estado erra."]'::jsonb, '[]'::jsonb, '["Art. 45"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-43' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '8280a546e47c04edda98b4ba8e44f3bff9e6a38d411f1eb015a576bc10d0fe91'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As medidas de proteção à pessoa idosa poderão ser aplicadas, isolada ou cumulativamente, e levarão em conta os fins sociais a que se destinam e o fortalecimento dos vínculos familiares e comunitários.', '["Aplicação isolada ou cumulativa.","Fortalecimento dos vínculos familiares e comunitários."]'::jsonb, '["Podem ser cumuladas."]'::jsonb, 'O juiz aplica mais de uma medida de proteção ao mesmo tempo.', '["Assertiva que proíbe cumular medidas de proteção erra."]'::jsonb, '[]'::jsonb, '["Art. 45"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-44' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '53cd1a4d9be8eae63080ebae921c90a3cdba3ea7a3e1c0612cdbdfc4dd6b47b8'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Verificada qualquer das hipóteses do art. 43, o Ministério Público ou o Poder Judiciário, a requerimento daquele, poderá determinar, entre outras, as seguintes medidas: encaminhamento à família ou curador, mediante termo de responsabilidade; orientação, apoio e acompanhamento temporários; requisição para tratamento de saúde, em regime ambulatorial, hospitalar ou domiciliar; inclusão em programa de auxílio e tratamento a usuários dependentes de drogas, da própria pessoa idosa ou de pessoa de sua convivência; abrigo em entidade; e abrigo temporário.', '["Encaminhamento à família ou curador.","Orientação e acompanhamento.","Tratamento de saúde.","Programa para dependentes de drogas.","Abrigo em entidade ou abrigo temporário."]'::jsonb, '["Rol exemplificativo (''dentre outras'')."]'::jsonb, 'O Ministério Público requisita o tratamento médico de uma pessoa idosa negligenciada.', '["Assertiva que considera taxativo o rol de medidas do art. 45 erra."]'::jsonb, '[]'::jsonb, '["Art. 43"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-45' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '5db96ed2d09feb8a89ebcec117bba4faea118056b13cc12de138be86f7004792'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A política de atendimento à pessoa idosa far-se-á por meio do conjunto articulado de ações governamentais e não governamentais da União, dos Estados, do Distrito Federal e dos Municípios.', '["Ações articuladas, governamentais e não governamentais.","União, Estados, DF e Municípios."]'::jsonb, '["Política articulada entre os entes e a sociedade civil."]'::jsonb, 'Município e entidades privadas atuam juntos no atendimento.', '["Assertiva que restringe a política à União erra."]'::jsonb, '[]'::jsonb, '["Art. 47"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-46' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'e520eba61e86305e067471f9fb8264fb1be638b8070aa09b87773f2ae182fac4'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São linhas de ação da política de atendimento as políticas sociais básicas da Política Nacional do Idoso; políticas e programas de assistência social, em caráter supletivo; serviços especiais de prevenção e atendimento às vítimas de negligência, maus-tratos, exploração, abuso, crueldade e opressão; serviço de identificação e localização de parentes ou responsáveis por pessoas idosas abandonadas em hospitais e instituições; proteção jurídico-social por entidades de defesa; e mobilização da opinião pública.', '["Políticas sociais básicas.","Assistência social supletiva.","Atendimento às vítimas de maus-tratos.","Localização de familiares de abandonados.","Proteção jurídico-social e mobilização da opinião pública."]'::jsonb, '["Assistência social é SUPLETIVA."]'::jsonb, 'Um serviço procura os parentes de uma pessoa idosa abandonada no hospital.', '["Assertiva que torna principal a assistência social no atendimento erra: ela é supletiva."]'::jsonb, '[]'::jsonb, '["Art. 46"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-47' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '49ebd6ce8386823496c6d08032c9ea017274b38555579ea73bec0b1a3492b079'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As entidades de atendimento são responsáveis pela manutenção das próprias unidades, observadas as normas de planejamento e execução da Política Nacional da Pessoa Idosa. As entidades governamentais e não governamentais ficam sujeitas à inscrição de seus programas perante a Vigilância Sanitária e o Conselho Municipal da Pessoa Idosa (ou Estadual ou Nacional, na falta), especificando os regimes de atendimento, com instalações adequadas de habitabilidade, higiene, salubridade e segurança; objetivos estatutários e plano de trabalho compatíveis; regular constituição; e idoneidade dos dirigentes.', '["Responsabilidade pela manutenção das unidades.","Inscrição dos programas na Vigilância Sanitária e no Conselho.","Requisitos: instalações, estatuto, constituição regular e idoneidade."]'::jsonb, '["Inscrição OBRIGATÓRIA dos programas."]'::jsonb, 'A casa de repouso inscreve seu programa no Conselho Municipal da Pessoa Idosa.', '["Assertiva que dispensa a inscrição dos programas das entidades erra."]'::jsonb, '[]'::jsonb, '["Art. 49"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-48' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '2c90f531b9e24f6ad1c928297d4babd9aae95d6c43b6548d3873378e310ef793'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As entidades de institucionalização de longa permanência adotarão os princípios da preservação dos vínculos familiares; atendimento personalizado e em pequenos grupos; manutenção da pessoa idosa na mesma instituição, salvo força maior; participação nas atividades comunitárias; observância dos direitos e garantias; e preservação da identidade, com ambiente de respeito e dignidade. O dirigente responderá civil e criminalmente pelos atos que praticar em detrimento da pessoa idosa, sem prejuízo das sanções administrativas.', '["Preservação dos vínculos familiares.","Atendimento personalizado em pequenos grupos.","Manutenção na mesma instituição.","Responsabilidade civil e criminal do dirigente."]'::jsonb, '["Dirigente responde civil e criminalmente."]'::jsonb, 'O dirigente que maltrata os abrigados responde civil e criminalmente.', '["Assertiva que isenta o dirigente da entidade de responsabilidade criminal erra."]'::jsonb, '[]'::jsonb, '["Art. 50"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-49' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '1f86e4e243d5146f1feda84ab110969d969a017337cbd9c2cced0ccf9241b8a4'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Constituem obrigações das entidades de atendimento: celebrar contrato escrito de prestação de serviço, especificando o atendimento, as obrigações e os preços; observar os direitos e garantias; fornecer vestuário adequado, se pública, e alimentação suficiente; oferecer instalações adequadas e atendimento personalizado; diligenciar a preservação dos vínculos familiares; oferecer acomodações para visitas; proporcionar cuidados à saúde; promover atividades educacionais, esportivas, culturais e de lazer; propiciar assistência religiosa; proceder a estudo social e pessoal; comunicar doenças infectocontagiosas; providenciar documentos de cidadania; fornecer comprovante de depósito dos bens móveis; e manter arquivo de anotações.', '["Contrato escrito.","Vestuário (se pública) e alimentação suficiente.","Cuidados à saúde e atividades de lazer.","Assistência religiosa.","Comprovante de depósito dos bens móveis."]'::jsonb, '["Vestuário adequado só se a entidade for PÚBLICA."]'::jsonb, 'A entidade entrega ao abrigado comprovante dos bens móveis que guarda.', '["Assertiva que dispensa o contrato escrito com a pessoa abrigada erra."]'::jsonb, '[]'::jsonb, '["Art. 56"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-50' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '99c991088be31d956857a7c0f0a39924f8270c4abc65ba1a55c1dd0c6580ef7f'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As instituições filantrópicas ou sem fins lucrativos prestadoras de serviço às pessoas idosas terão direito à assistência judiciária gratuita.', '["Assistência judiciária gratuita às entidades filantrópicas."]'::jsonb, '["Vale para filantrópicas e sem fins lucrativos."]'::jsonb, 'A entidade filantrópica litiga sem pagar custas.', '["Assertiva que nega assistência judiciária às entidades sem fins lucrativos erra."]'::jsonb, '[]'::jsonb, '["Art. 88"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-51' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'e7975542e0bbc2c1648d4a44d5a25c819559fa7dc9a8cbf16a5036331ca17c49'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As entidades governamentais e não governamentais de atendimento à pessoa idosa serão fiscalizadas pelos Conselhos da Pessoa Idosa, Ministério Público, Vigilância Sanitária e outros previstos em lei.', '["Fiscalização por Conselhos, MP e Vigilância Sanitária."]'::jsonb, '["Múltiplos fiscalizadores."]'::jsonb, 'A Vigilância Sanitária inspeciona a casa de repouso.', '["Assertiva que atribui a fiscalização apenas ao Ministério Público erra."]'::jsonb, '[]'::jsonb, '["Art. 7º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-52' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '60eb133069ecf7ba561c1d54479321405fd92a0e11c1f592a79ba6657836f9d1'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O art. 7º da Lei da Política Nacional do Idoso passa a prever que compete aos Conselhos a supervisão, o acompanhamento, a fiscalização e a avaliação da política nacional do idoso, no âmbito de suas instâncias político-administrativas.', '["Altera o art. 7º da Lei nº 8.842, de 1994.","Conselhos supervisionam e avaliam a política."]'::jsonb, '["ATUALIZAÇÃO: altera a Lei nº 8.842, de 1994."]'::jsonb, 'O Conselho avalia a política de atendimento do Município.', '["Assertiva que retira dos Conselhos o poder de fiscalizar a política erra."]'::jsonb, '[]'::jsonb, '["Art. 7º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-53' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '41c45d4129531b459d31ed3101b9ac3fdd10d3dcff0d1f415f32e88b823b4c09'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Será dada publicidade das prestações de contas dos recursos públicos e privados recebidos pelas entidades de atendimento.', '["Publicidade das prestações de contas."]'::jsonb, '["Transparência de recursos públicos e privados."]'::jsonb, 'A entidade divulga como aplicou as doações recebidas.', '["Assertiva que mantém sigilo das contas das entidades erra."]'::jsonb, '[]'::jsonb, '["Art. 55"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-54' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '0581b90e257e562c9342b852a35de41bba0d0408fab44c8881b541f64093b5fc'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As entidades de atendimento que descumprirem a Lei ficarão sujeitas, sem prejuízo da responsabilidade civil e criminal dos dirigentes, a penalidades, observado o devido processo legal. As governamentais: advertência, afastamento provisório ou definitivo dos dirigentes e fechamento de unidade ou interdição de programa. As não governamentais: advertência, multa, suspensão parcial ou total do repasse de verbas públicas, interdição de unidade ou suspensão de programa e proibição de atendimento a pessoas idosas. Havendo danos ou fraude, cabe afastamento provisório dos dirigentes ou interdição. A suspensão do repasse ocorre em caso de má aplicação ou desvio. Infração que coloque em risco os direitos é comunicada ao Ministério Público.', '["Penalidades distintas para entidades governamentais e não governamentais.","Multa só para as não governamentais.","Suspensão de repasse por desvio.","Comunicação ao Ministério Público."]'::jsonb, '["MULTA só às entidades NÃO governamentais."]'::jsonb, 'A entidade privada que desvia verba perde o repasse público.', '["Assertiva que aplica multa às entidades governamentais erra: a multa é para as não governamentais."]'::jsonb, '[]'::jsonb, '["Art. 56"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-55' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'a9f011b1c6823c60e0ea3a6dd38f5cf2ca0bfe323dfb7a42aadbf80e4149024e'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Deixar a entidade de atendimento de cumprir as determinações do art. 50: multa de R$ 500,00 a R$ 3.000,00, se o fato não for crime, podendo haver interdição do estabelecimento até que sejam cumpridas as exigências. No caso de interdição de estabelecimento de longa permanência, as pessoas idosas serão transferidas para outra instituição, a expensas do estabelecimento interditado, durante a interdição.', '["Multa de R$ 500,00 a R$ 3.000,00.","Interdição até o cumprimento das exigências.","Transferência dos abrigados às expensas do estabelecimento."]'::jsonb, '["A transferência dos abrigados é custeada pelo estabelecimento interditado."]'::jsonb, 'A casa de repouso interditada paga a transferência dos abrigados.', '["Assertiva que transfere ao Estado o custo do abrigo na interdição erra: é do estabelecimento."]'::jsonb, '[]'::jsonb, '["Art. 50"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-56' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '1e443161a37bbf4e1e9bf7f6a6dd388d5b04996d0c982faca357143d18c0f83c'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
