select u.id, u.content_sha256, 'Havendo motivo grave, poderá a autoridade judiciária, ouvido o Ministério Público, decretar liminarmente o afastamento provisório do dirigente da entidade ou outras medidas que julgar adequadas, para evitar lesão aos direitos da pessoa idosa, mediante decisão fundamentada.', '["Afastamento provisório do dirigente, liminarmente.","Ouvido o Ministério Público.","Decisão fundamentada."]'::jsonb, '["Exige MOTIVO GRAVE."]'::jsonb, 'O juiz afasta provisoriamente o dirigente suspeito de maus-tratos.', '["Assertiva que dispensa fundamentação do afastamento erra."]'::jsonb, '[]'::jsonb, '["Art. 65"]'::jsonb, 'under_review', 'claude'
