insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Apresentada a defesa, o juiz procederá na conformidade do art. 69 ou, se necessário, designará audiência de instrução e julgamento. Salvo manifestação em audiência, as partes e o Ministério Público terão 5 dias para alegações finais, decidindo a autoridade judiciária em igual prazo. No afastamento de dirigente de entidade governamental, a autoridade oficia a autoridade administrativa superior, fixando prazo de 24 horas para a substituição. Antes de aplicar as medidas, poderá fixar prazo para remover as irregularidades, e, satisfeitas as exigências, o processo será extinto sem julgamento do mérito. A multa e a advertência são impostas ao dirigente ou ao responsável pelo programa.', '["Alegações finais em 5 dias; decisão em igual prazo.","Substituição do dirigente governamental em 24 horas.","Prazo para remover irregularidades e extinção do processo.","Multa e advertência ao dirigente."]'::jsonb, '["Substituição em 24 horas.","Cumpridas as exigências, o processo é extinto SEM julgamento do mérito."]'::jsonb, 'A entidade corrige as irregularidades no prazo e o processo é extinto.', '["Assertiva que impõe a multa à entidade e não ao dirigente erra: é imposta ao dirigente ou responsável."]'::jsonb, '[]'::jsonb, '["Art. 69"]'::jsonb, 'under_review', 'claude'
