insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O artigo altera o Código Penal para endurecer a proteção à pessoa idosa: cria a agravante contra criança, maior de 60 anos, enfermo ou mulher grávida (art. 61); aumenta de 1/3 o homicídio doloso contra maior de 60 anos e o culposo em hipóteses de inobservância e fuga (art. 121); inclui causa de aumento no abandono de incapaz se a vítima é maior de 60 anos (art. 133); prevê injúria com elementos referentes à condição de pessoa idosa (art. 140); aumenta os crimes contra a honra contra maior de 60 anos (art. 141); qualifica o sequestro de maior de 60 anos (art. 148) e a extorsão mediante sequestro de maior de 60 anos (art. 159); e ajusta imunidades no art. 183.', '["Agravante: maior de 60 anos (art. 61).","Homicídio: aumento de 1/3 contra maior de 60 anos.","Sequestro e extorsão mediante sequestro de maior de 60 anos qualificados.","Injúria com elementos da condição de pessoa idosa."]'::jsonb, '["ATUALIZAÇÃO: altera o Código Penal; algumas redações foram alteradas por leis posteriores. Confira o texto vigente."]'::jsonb, 'O sequestro de uma pessoa de 70 anos é qualificado.', '["Assertiva que não considera agravante o crime contra maior de 60 anos erra."]'::jsonb, '[]'::jsonb, '["Código Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-110' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'ceacd0bf10afd2e7b0615ab932b912f36687d744ad8f922b4843e558fc503339'
