insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Poder Executivo encaminhará ao Congresso Nacional projeto de lei revendo os critérios de concessão do Benefício de Prestação Continuada previsto na Lei Orgânica da Assistência Social, de forma a garantir que o acesso ao direito seja condizente com o estágio de desenvolvimento socioeconômico alcançado pelo País.', '["Projeto de lei revendo critérios do BPC."]'::jsonb, '["Dispositivo programático."]'::jsonb, 'O Executivo deveria propor a revisão dos critérios do BPC.', '["Assertiva que já altera por si os critérios do BPC erra: ela apenas determina o envio de projeto."]'::jsonb, '[]'::jsonb, '["Art. 34"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-117' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '041d732ec54db7039001ffe33692eb09834c556ca57e7c77f6d38b667430c98d'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Esta Lei entra em vigor decorridos 90 dias da sua publicação, ressalvado o disposto no caput do art. 36, que vigorará a partir de 1º de janeiro de 2004.', '["Vacatio legis de 90 dias.","Art. 36 vigora a partir de 1º de janeiro de 2004."]'::jsonb, '["Vacatio legis de 90 dias."]'::jsonb, 'O Estatuto só passou a valer noventa dias após a publicação.', '["Assertiva que prevê vigência imediata erra: são 90 dias."]'::jsonb, '[]'::jsonb, '["Art. 36"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'idosa' and u.unit_key = 'art-118' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '78e911dbbe0978e18862053b26027c3f820ebe4bb55656aeeaf8d3afbba45982'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;
